static const struct airlink_glyph *font_medium_17_find(uint32_t cp)
{
    uint32_t lo=0U, hi=(uint32_t)(sizeof(font_medium_17_glyphs)/sizeof(font_medium_17_glyphs[0]));
    while(lo<hi){uint32_t mid=lo+(hi-lo)/2U; if(font_medium_17_glyphs[mid].cp<cp) lo=mid+1U; else hi=mid;}
    return lo<(uint32_t)(sizeof(font_medium_17_glyphs)/sizeof(font_medium_17_glyphs[0])) && font_medium_17_glyphs[lo].cp==cp ? &font_medium_17_glyphs[lo] : NULL;
}
static bool font_medium_17_dsc(const lv_font_t *font, lv_font_glyph_dsc_t *out, uint32_t cp, uint32_t next)
{
    const struct airlink_glyph *g=font_medium_17_find(cp); (void)next; if(!g) return false;
    out->resolved_font=font; out->adv_w=(uint16_t)((g->adv+8U)>>4); out->box_w=g->w; out->box_h=g->h;
    out->ofs_x=g->ofs_x; out->ofs_y=g->ofs_y; out->bpp=4; out->is_placeholder=0; return true;
}
static const uint8_t *font_medium_17_bitmap_cb(const lv_font_t *font, uint32_t cp)
{
    const struct airlink_glyph *g=font_medium_17_find(cp); (void)font; return g ? font_medium_17_bitmap+g->offset : NULL;
}
